CREATE POLICY "roster_links_update_target_owner" ON public.team_roster_player_links FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.teams t WHERE t.id = (team_roster_player_links.target_team_id)::text AND t.user_id = (auth.uid())::text)) WITH CHECK (EXISTS (SELECT 1 FROM public.teams t WHERE t.id = (team_roster_player_links.target_team_id)::text AND t.user_id = (auth.uid())::text));